com.mirth.connect.plugins.javascriptstep.script:
channelMap.put('patientName', msg['PID']['PID.5']['PID.5.1'].toString());
var rawContent = String(connectorMessage.getRawData());
var htmlSafeContent = rawContent.replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
channelMap.put('htmlSafeContent', htmlSafeContent);

// Phase 22.3 (SC-3): mirrors DocRenderSeamTest#buildLargeMultiTableHtml (22.3-01) verbatim --
// same token constants, same 5-table x 80-row shape, same token placement -- so the end-to-end
// smoke fixture is auditably identical to the seam-level fixture.
var MPAGE_TABLE_COUNT = 5;
var MPAGE_ROWS_PER_TABLE = 80;
var MPAGE_TABLE_TOKENS = ['MPAGE_TABLE_TOKEN_1_22P3', 'MPAGE_TABLE_TOKEN_2_22P3', 'MPAGE_TABLE_TOKEN_3_22P3',
        'MPAGE_TABLE_TOKEN_4_22P3', 'MPAGE_TABLE_TOKEN_5_22P3'];
var MPAGE_LAST_ROW_TOKEN_22P3 = 'MPAGE_LAST_ROW_TOKEN_22P3';
var MPAGE_ACCENTED_EARLY = 'José';
var MPAGE_ACCENTED_LATE = 'Müller';

var sb = '<html><body>';
for (var t = 0; t < MPAGE_TABLE_COUNT; t++) {
    sb += '<table>';
    for (var r = 0; r < MPAGE_ROWS_PER_TABLE; r++) {
        sb += '<tr><td>';
        if (r == 0 && t < MPAGE_TABLE_TOKENS.length) {
            sb += MPAGE_TABLE_TOKENS[t] + ' ';
        }
        if (t == 0 && r == 1) {
            sb += MPAGE_ACCENTED_EARLY + ' ';
        }
        if (t == MPAGE_TABLE_COUNT - 2 && r == 1) {
            sb += MPAGE_ACCENTED_LATE + ' ';
        }
        if (t == MPAGE_TABLE_COUNT - 1 && r == MPAGE_ROWS_PER_TABLE - 1) {
            sb += MPAGE_LAST_ROW_TOKEN_22P3 + ' ';
        }
        sb += 'row ' + t + '-' + r;
        sb += '</td></tr>';
    }
    sb += '</table>';
}
sb += '</body></html>';

channelMap.put('largeDocContent', sb);

// UAT (26.6.0 -> 26.9.0 regression): build a realistic, fully-styled discharge
// summary -- headings with a rule line, a demographics table, and shaded-header
// diagnoses + medication tables -- so the Document Writer exercises a normal
// styled-document use case (not the bare <table><td> smoke fixtures). Rendered
// to BOTH PDF and RTF by OpenPDF; mirrors ~/Downloads/discharge-summary.{pdf,rtf}.
var famName = msg['PID']['PID.5']['PID.5.1'].toString();
var givName = msg['PID']['PID.5']['PID.5.2'].toString();
var patient = (famName + (givName ? ', ' + givName : '')) || 'UNKNOWN';
var mrn = msg['PID']['PID.3']['PID.3.1'].toString();
var dobRaw = msg['PID']['PID.7']['PID.7.1'].toString();
if (!dobRaw) { dobRaw = msg['PID']['PID.7'].toString(); }
var dob = (dobRaw && dobRaw.length >= 8)
        ? (dobRaw.substr(0, 4) + '-' + dobRaw.substr(4, 2) + '-' + dobRaw.substr(6, 2))
        : dobRaw;
var sex = msg['PID']['PID.8'].toString();

var css = 'body { font-family: Helvetica, Arial, sans-serif; font-size: 11pt; color:#222; margin: 24px; }'
        + ' h1 { color:#1a4b7a; border-bottom: 2px solid #1a4b7a; padding-bottom:4px; }'
        + ' h2 { color:#1a4b7a; font-size: 13pt; margin-top: 18px; }'
        + ' table { border-collapse: collapse; width: 100%; margin-top: 8px; }'
        + ' th, td { border: 1px solid #888; padding: 6px 8px; text-align:left; font-size:10pt; }'
        + ' th { background:#e8eff6; }'
        + ' thead { display: table-header-group; }'
        + ' tr { page-break-inside: avoid; }'
        + ' .muted { color:#666; font-size: 9pt; }'
        + ' .page-break { page-break-before: always; }'
        + ' table.header { margin: 0; }'
        + ' table.header td { border: none; padding: 0; vertical-align: middle; }'
        + ' td.logocell { width: 64px; }'
        + ' img.logo { width: 54px; height: 54px; }'
        + ' td.titlecell h1 { margin: 0; border: none; padding: 0; }'
        + ' .rule { border-bottom: 2px solid #1a4b7a; margin: 2px 0 10px 0; }'
        + ' @page {'
        + '   @bottom-left { content: "Innovar General Hospital - Confidential"; font-size: 8pt; color: #666; }'
        + '   @bottom-center { content: "Discharge Summary"; font-size: 8pt; color: #666; }'
        + '   @bottom-right { content: "Page " counter(page) " of " counter(pages); font-size: 8pt; color: #666; }'
        + ' }';

// Small on-brand logo embedded as a base64 PNG data URI. openhtmltopdf (the PDF
// engine, identical in 26.6.0 and 26.9.0) renders data: image URIs natively; the
// legacy HTML->RTF parser does not, so the logo is a PDF-path feature.
var logo = 'data:image/png;base64,';

var h = '<html><head><style>' + css + '</style></head><body>';
h += '<table class="header"><tr>'
   + '<td class="logocell"><img class="logo" src="' + logo + '" alt="logo"/></td>'
   + '<td class="titlecell"><h1>Discharge Summary</h1>'
   + '<p class="muted">Innovar General Hospital — Generated by BridgeLink Document Writer</p></td>'
   + '</tr></table>';
h += '<div class="rule"></div>';
h += '<table>'
   + '<tr><th>Patient</th><td>' + patient + '</td><th>MRN</th><td>' + mrn + '</td></tr>'
   + '<tr><th>DOB</th><td>' + dob + '</td><th>Sex</th><td>' + sex + '</td></tr>'
   + '<tr><th>Admit</th><td>2026-08-05</td><th>Discharge</th><td>2026-08-11</td></tr>'
   + '</table>';
h += '<h2>Diagnoses</h2><table>'
   + '<tr><th>Code</th><th>Description</th></tr>'
   + '<tr><td>I21.4</td><td>Non-ST elevation myocardial infarction</td></tr>'
   + '<tr><td>E11.9</td><td>Type 2 diabetes mellitus without complications</td></tr>'
   + '<tr><td>I10</td><td>Essential (primary) hypertension</td></tr>'
   + '</table>';
h += '<h2>Discharge Medications</h2><table>'
   + '<tr><th>Drug</th><th>Dose</th><th>Route</th><th>Frequency</th></tr>'
   + '<tr><td>Aspirin</td><td>81 mg</td><td>PO</td><td>Daily</td></tr>'
   + '<tr><td>Atorvastatin</td><td>40 mg</td><td>PO</td><td>Nightly</td></tr>'
   + '<tr><td>Metoprolol</td><td>25 mg</td><td>PO</td><td>BID</td></tr>'
   + '</table>';
// ---- Multi-page content (26.6.0 -> 26.9.0 multi-page regression) ----
// Deterministic (no randomness) so the document is byte-comparable before/after.

// Hospital Course narrative -- several paragraphs of flowing text.
h += '<h2>Hospital Course</h2>';
var courseDays = ['presented to the emergency department with acute chest pain and was found to have an NSTEMI',
                  'underwent coronary angiography with drug-eluting stent placement to the mid-LAD',
                  'was transferred to the cardiac step-down unit in stable condition',
                  'had glycemic control optimized with the addition of long-acting insulin',
                  'was ambulating independently and tolerating a cardiac diet',
                  'completed cardiac rehabilitation teaching with nursing',
                  'was deemed medically stable for discharge to home'];
for (var d = 0; d < courseDays.length; d++) {
  h += '<p><strong>Hospital Day ' + (d + 1) + ':</strong> The patient ' + courseDays[d]
     + '. Vital signs remained within acceptable limits, and the patient reported '
     + 'progressive improvement in symptoms. The multidisciplinary team reviewed the plan of care '
     + 'and adjusted medications as clinically indicated. No acute events were noted overnight.</p>';
}

// Laboratory Results -- long table (60 rows) that spans several pages;
// <thead> repeats the header row on each page. Row tokens LAB-0001..LAB-0060.
h += '<h2 class="page-break">Laboratory Results (Serial)</h2><table>'
   + '<thead><tr><th>#</th><th>Result ID</th><th>Analyte</th><th>Value</th><th>Units</th><th>Reference</th><th>Flag</th></tr></thead>'
   + '<tbody>';
var analytes = [['Sodium','mmol/L','135-145'],['Potassium','mmol/L','3.5-5.1'],['Chloride','mmol/L','98-107'],
                ['CO2','mmol/L','22-29'],['BUN','mg/dL','7-20'],['Creatinine','mg/dL','0.6-1.3'],
                ['Glucose','mg/dL','70-99'],['Troponin I','ng/mL','under 0.04'],['Hemoglobin','g/dL','12-16'],
                ['Platelets','K/uL','150-400']];
for (var i = 1; i <= 60; i++) {
  var a = analytes[(i - 1) % analytes.length];
  var val = (10 + ((i * 7) % 90)) + '.' + (i % 10);
  var flag = ((i % 9) === 0) ? 'H' : ((i % 13) === 0 ? 'L' : '');
  var rid = 'LAB-' + ('000' + i).slice(-4);
  h += '<tr><td>' + i + '</td><td>' + rid + '</td><td>' + a[0] + '</td><td>' + val + '</td><td>'
     + a[1] + '</td><td>' + a[2] + '</td><td>' + flag + '</td></tr>';
}
h += '</tbody></table>';

// Daily Progress Notes -- 14 dated blocks, each with a small vitals table.
h += '<h2 class="page-break">Daily Progress Notes</h2>';
for (var n = 1; n <= 14; n++) {
  var day = ('0' + n).slice(-2);
  h += '<h2>Progress Note 2026-08-' + day + '</h2>'
     + '<p><strong>NOTE-' + ('00' + n).slice(-3) + '.</strong> Subjective: patient resting comfortably, '
     + 'no new complaints. Objective: examination unchanged from prior. Assessment: stable, improving. '
     + 'Plan: continue current regimen, reassess in the morning.</p>'
     + '<table><thead><tr><th>Time</th><th>Temp (F)</th><th>HR</th><th>BP</th><th>SpO2</th></tr></thead>'
     + '<tbody>'
     + '<tr><td>08:00</td><td>98.' + (n % 9) + '</td><td>' + (62 + n) + '</td><td>' + (118 + n) + '/' + (70 + (n % 10)) + '</td><td>9' + (5 + (n % 4)) + '%</td></tr>'
     + '<tr><td>20:00</td><td>98.' + ((n + 3) % 9) + '</td><td>' + (60 + n) + '</td><td>' + (116 + n) + '/' + (68 + (n % 10)) + '</td><td>9' + (6 + (n % 3)) + '%</td></tr>'
     + '</tbody></table>';
}

h += '<h2 class="page-break">Follow-up</h2>';
h += '<p>Cardiology clinic in 1 week. Primary care in 2 weeks. Return to ED for chest pain, '
   + 'shortness of breath, or fever &gt; 100.4°F.</p>';
h += '<p class="muted">Attending: Dr. José Müller-Bergström, MD  |  Signed 2026-08-11 14:32</p>';
h += '<p class="muted"><strong>END OF DISCHARGE SUMMARY — RECORD ZZ-END-9999</strong></p>';
h += '</body></html>';

// RTF variant: the legacy HTML->RTF parser (com.lowagie.text.html.HtmlParser)
// tries to load <img src> as a file/URL and throws FileNotFoundException on a
// data: URI, failing the whole RTF destination. So strip the logo <img> for RTF
// (the logo is a PDF-only feature), and flatten thead/tbody to the plain <tr>
// form the RTF parser renders reliably. PDF keeps the full logo version.
var hRtf = h.replace(/<img[^>]*>/g, '')
            .replace(/<\/?(thead|tbody)>/g, '');
channelMap.put('dischargeSummaryHtml', h);
channelMap.put('dischargeSummaryRtf', hRtf);
